use vstd::prelude::*;

verus! {

fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (res: Vec<f64>)
    requires
        // The index array is non‐empty
        indices.len() > 0,
        // The matrix has at least one row
        choices.len() > 0,
        // Every row has the same length as the indices
        forall |r: usize| r < choices.len() ==>
            choices[r].len() == indices.len(),
        // Every index is a valid row selector
        forall |i: usize| i < indices.len() ==>
            (indices[i] as usize) < choices.len(),
    ensures
        // The result has the same length as indices
        res.len() == indices.len(),
        // And for each position i, res[i] == choices[ indices[i] ][ i ]
        forall |i: usize| i < indices.len() ==>
            res[i] == choices[indices[i] as usize][i],
{
    let mut res: Vec<f64> = Vec::new();
    let n = indices.len();
    let mut idx: usize = 0;
    while idx < n
        invariant
            // loop index stays in bounds
            idx <= n,
            // we've built res up to idx
            res.len() == idx,
            // and for each 0 <= j < idx, res[j] matches the spec
            forall |j: usize| j < idx ==>
                res[j] == choices[indices[j] as usize][j],
        decreases n - idx,
    {
        let i = idx;
        let row = indices[i] as usize;
        // by the precondition, row < choices.len()
        let v: f64 = choices[row][i];
        res.push(v);
        idx += 1;
    }
    res
}

}

